// One block per risky rule: what it does, rows affected, examples from the dry run, and an Approve / Reject choice
const rules = $input.all().map(i => i.json).filter(r => r.rule_id);
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const show = v => esc(v === null || v === undefined ? 'null' : typeof v === 'string' ? `"${v}"` : JSON.stringify(v));
if (rules.length === 0) {
  return [{ json: { rules: [], form_fields: JSON.stringify([
    { fieldType: 'html', html: '<p>Nothing is waiting for approval right now.</p>' }]) } }];
}
const fields = [];
rules.forEach((r, i) => {
  const examples = (r.examples ?? []).map(e => 'before' in e
    ? `<li><code>${show(e.before)}</code> → <code>${show(e.after)}</code></li>`
    : `<li><code>${show(e)}</code> → removed</li>`).join('');
  fields.push({ fieldType: 'html', html:
    `<h3>Rule ${i + 1} · ${esc(r.source)}${r.column_name ? ` · ${esc(r.column_name)}` : ''}</h3>` +
    `<p><b>${esc(r.rule_type)}</b> <code>${esc(JSON.stringify(r.params))}</code></p>` +
    `<p>${esc(r.reason)}</p>` +
    `<p>Rows affected in the dry run: <b>${r.rows_affected ?? '?'}</b> · agent confidence ${r.confidence} · ` +
    `needs approval because it ${esc(r.risk_reason)}</p>` +
    (examples ? `<ul>${examples}</ul>` : '') });
  fields.push({ fieldLabel: `Rule ${i + 1}`, fieldType: 'radio', requiredField: true,
                fieldOptions: { values: [{ option: 'Approve' }, { option: 'Reject' }] } });
});
return [{ json: { rules: rules.map(r => r.rule_id), run_id: rules[0].waiting_run_id, resume_url: rules[0].resume_url,
                  form_fields: JSON.stringify(fields) } }];

// Turn the answers into one decision per rule. 'Rule 1', 'Rule 2' ... are the radio fields on the review page.
const page = $input.first().json;
const meta = $('Build review page').first().json;
const approver = $('Open approval form').first().json['Your name'];
const lit = v => `'${String(v).replace(/'/g, "''")}'`;
const decisions = meta.rules.map((rule_id, i) => ({ rule_id, status: page[`Rule ${i + 1}`] === 'Approve' ? 'approved' : 'rejected' }));
return [{ json: {
  run_id: meta.run_id ?? null,
  resume_url: meta.resume_url ?? null,
  approver,
  decided: decisions.length,
  approved: decisions.filter(d => d.status === 'approved').length,
  rejected: decisions.filter(d => d.status === 'rejected').length,
  values_sql: decisions.map(d => `(${lit(d.rule_id)}, ${lit(d.status)}, ${lit(approver)})`).join(',\n       '),
} }];

