=-- Store every decision, and mark the waiting run as answered
update ops.cleaning_rules r
set status = d.status, decided_by = d.decided_by, decided_at = now()
from (values {{ $json.values_sql }}) as d(rule_id, status, decided_by)
where r.rule_id = d.rule_id and r.status = 'pending';
update ops.cleaning_approvals set status = 'submitted', submitted_at = now()
where run_id = '{{ $json.run_id }}' and status = 'waiting';
select count(*)::int as decided from ops.cleaning_rules where decided_at > now() - interval '1 minute';

